# Configuration
BASE_URLS = {
    'supreme_court': 'https://judiciary.gov.gh/supreme-court/judgments',
    'court_of_appeal': 'https://judiciary.gov.gh/court-of-appeal/rulings',
    'high_court': 'https://judiciary.gov.gh/high-court/decisions',
    'practice_directions': 'https://judiciary.gov.gh/practice-directions'
}

HEADERS = {
    'User-Agent': 'LegalKBSeeder/1.0',
    'Accept-Encoding': 'gzip, deflate',
    'Connection': 'keep-alive'
}

# Create necessary directories
os.makedirs('data/supreme_court', exist_ok=True)
os.makedirs('data/court_of_appeal', exist_ok=True)
os.makedirs('data/high_court', exist_ok=True)
os.makedirs('data/practice_directions', exist_ok=True)
os.makedirs('logs', exist_ok=True)

# Logging configuration
logging.basicConfig(
    filename='logs/scraper_errors.log',
    level=logging.ERROR,
    format='%(asctime)s - %(levelname)s - %(message)s'
)

def get_page_content(url: str) -> Optional[str]:
    """Fetch page content with retry logic."""
    for attempt in range(3):
        try:
            response = requests.get(url, headers=HEADERS, timeout=10)
            response.raise_for_status()
            return response.text
        except requests.exceptions.RequestException as e:
            logging.error(f"Request failed for {url}: {str(e)}")
            if attempt < 2:
                time.sleep(2 ** attempt)
    return None

def parse_date(date_str: str) -> str:
    """Parse date string to ISO format."""
    try:
        from dateutil import parser
        dt = parser.parse(date_str)
        return dt.strftime('%Y-%m-%d')
    except:
        return date_str

def scrape_documents(base_url: str, court_level: str) -> List[Dict]:
    """Scrape document metadata from a court page."""
    documents = []
    page_num = 1
    
    while True:
        if page_num > 1:
            paginated_url = f"{base_url}?page={page_num}"
        else:
            paginated_url = base_url
            
        html_content = get_page_content(paginated_url)
        if not html_content:
            break
            
        soup = BeautifulSoup(html_content, 'html.parser')
        
        # Example selector - adjust based on actual HTML structure
        entries = soup.select('.document-list .entry')  # Change based on real class
        
        if not entries:
            break
            
        for entry in entries:
            try:
                title_elem = entry.select_one('h3.title a')  # Adjust selector
                url = urljoin(base_url, title_elem['href']) if title_elem else ''
                title = title_elem.text.strip() if title_elem else 'Untitled'
                
                date_elem = entry.select_one('.date')  # Adjust selector
                date_str = date_elem.text.strip() if date_elem else ''
                formatted_date = parse_date(date_str)
                
                doc_type = 'judgment' if 'judgment' in base_url else \
                          'ruling' if 'appeal' in base_url else \
                          'decision' if 'high-court' in base_url else 'practice_direction'
                
                documents.append({
                    'title': title,
                    'url': url,
                    'date': formatted_date,
                    'court_level': court_level,
                    'document_type': doc_type
                })
            except Exception as e:
                logging.error(f"Error parsing entry: {str(e)}")
                
        # Check for next page - adjust based on actual pagination
        next_button = soup.select_one('.pagination .next')  # Change selector
        if not next_button:
            break
            
        page_num += 1
        time.sleep(1)  # Rate limiting
        
    return documents

def download_pdf(doc_metadata: Dict, db_conn: sqlite3.Connection) -> Optional[str]:
    """Download PDF and save with checksum."""
    cursor = db_conn.cursor()
    
    # Check if already exists
    cursor.execute("SELECT * FROM documents WHERE url = ? OR checksum = ?",
                  (doc_metadata['url'], doc_metadata.get('checksum')))
    if cursor.fetchone():
        return None
        
    try:
        response = requests.get(doc_metadata['url'], headers=HEADERS, timeout=10)
        response.raise_for_status()
        
        # Calculate checksum
        pdf_content = response.content
        checksum = hashlib.sha256(pdf_content).hexdigest()
        
        # Save file
        court_dir = f"data/{doc_metadata['court_level']}"
        file_path = os.path.join(court_dir, f"{checksum}.pdf")
        
        with open(file_path, 'wb') as f:
            f.write(pdf_content)
            
        doc_metadata['checksum'] = checksum
        doc_metadata['file_path'] = file_path
        
        return checksum
    except Exception as e:
        logging.error(f"Download failed for {doc_metadata['url']}: {str(e)}")
        return None

def init_db():
    """Initialize SQLite database."""
    conn = sqlite3.connect('legal_knowledge_base.db')
    cursor = conn.cursor()
    cursor.execute("""
        CREATE TABLE IF NOT EXISTS documents (
            id INTEGER PRIMARY KEY,
            url TEXT NOT NULL UNIQUE,
            title TEXT NOT NULL,
            court_level TEXT NOT NULL,
            document_type TEXT NOT NULL,
            date DATE NOT NULL,
            file_path TEXT NOT NULL,
            checksum TEXT NOT NULL
        )
    """)
    conn.commit()
    return conn

def store_metadata(conn: sqlite3.Connection, documents: List[Dict]):
    """Store document metadata in database."""
    cursor = conn.cursor()
    
    for doc in documents:
        try:
            cursor.execute("""
                INSERT INTO documents 
                (url, title, court_level, document_type, date, file_path, checksum)
                VALUES (?, ?, ?, ?, ?, ?, ?)
            """, (
                doc['url'],
                doc['title'],
                doc['court_level'],
                doc['document_type'],
                doc['date'],
                doc['file_path'],
                doc['checksum']
            ))
        except sqlite3.IntegrityError:
            # Document already exists
            continue
    
    conn.commit()

def export_to_json(conn: sqlite3.Connection):
    """Export database to JSON file."""
    cursor = conn.cursor()
    cursor.execute("SELECT * FROM documents")
    rows = cursor.fetchall()
    
    columns = [col[0] for col in cursor.description]
    data = [dict(zip(columns, row)) for row in rows]
    
    with open('metadata.json', 'w') as f:
        json.dump(data, f, indent=2)

def run_scraper():
    """Main orchestrator function."""
    conn = init_db()
    
    for court, url in BASE_URLS.items():
        print(f"Scraping {court} documents...")
        documents = scrape_documents(url, court)
        
        if documents:
            print(f"Found {len(documents)} documents for {court}")
            
            for doc in documents:
                checksum = download_pdf(doc, conn)
                if checksum:
                    print(f"Downloaded {doc['title']} ({checksum[:8]}...)")
            
            store_metadata(conn, documents)
            export_to_json(conn)
        else:
            print(f"No documents found for {court}")
            
        time.sleep(2)  # Rate limiting between court levels
        
    conn.close()

# Tests
def test_scrape_documents():
    mock_html = """
    <html>
        <div class="document-list">
            <div class="entry">
                <h3 class="title"><a href="/doc1.pdf">Sample Judgment</a></h3>
                <div class="date">2023-04-05</div>
            </div>
            <div class="entry">
                <h3 class="title"><a href="/doc2.pdf">Another Ruling</a></h3>
                <div class="date">05 Apr 2023</div>
            </div>
        </div>
        <div class="pagination"><span class="next">Next</span></div>
    </html>
    """
    
    with patch('requests.get') as mock_get:
        mock_response = MagicMock()
        mock_response.status_code = 200
        mock_response.text.return_value = mock_html
        mock_response.content.return_value = mock_html.encode()
        mock_get.return_value = mock_response
        
        results = scrape_documents("http://test.com", "test_court")
        assert len(results) == 2
        assert results[0]['title'] == "Sample Judgment"
        assert results[1]['date'] == "2023-04-05"

