def test_database_operations():
    conn = init_db()
    test_doc = {
        'url': 'http://test.com/doc.pdf',
        'title': 'Database Test',
        'court_level': 'test',
        'document_type': 'test',
        'date': '2023-01-01',
        'checksum': 'a' * 64,
        'file_path': 'data/test/a.pdf'
    }
    
    store_metadata(conn, [test_doc])
    cursor = conn.cursor()
